cpp.setup:
auto* hostLayout = new QVBoxLayout(%PARENT%);
hostLayout->setContentsMargins(0, 0, 0, 0);
auto* card = new fluent::layout::Card(%PARENT%);
hostLayout->addWidget(card);
auto* cardLayout = new QVBoxLayout(card);
cardLayout->setContentsMargins(16, 12, 16, 14);
cardLayout->setSpacing(6);
auto* heading = new fluent::textfields::Label(QStringLiteral("Current location"), card);
heading->setFluentTypography(Typography::FontRole::Caption);
heading->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
cardLayout->addWidget(heading);
auto* control = new fluent::navigation::Breadcrumb(card);
control->setItems({fluent::navigation::BreadcrumbItem(QStringLiteral("Workspace")), fluent::navigation::BreadcrumbItem(QStringLiteral("Engineering")), fluent::navigation::BreadcrumbItem(QStringLiteral("FluentQt")), fluent::navigation::BreadcrumbItem(QStringLiteral("Components")), fluent::navigation::BreadcrumbItem(QStringLiteral("Navigation")), fluent::navigation::BreadcrumbItem(QStringLiteral("Breadcrumb"))});
cardLayout->addWidget(control);
auto* summary = new fluent::textfields::Label(QStringLiteral("Path depth: 6 levels"), card);
summary->setFluentTypography(Typography::FontRole::Caption);
summary->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
cardLayout->addStretch(1);
cardLayout->addWidget(summary);
auto* overflowMenu = new fluent::menus_toolbars::FluentMenu(QStringLiteral("Overflow"), control);
QObject::connect(control, &fluent::navigation::Breadcrumb::itemsChanged, summary, [control, summary] {
    summary->setText(control->itemCount() == 0 ? QStringLiteral("Empty path") : QStringLiteral("Path depth: %1 levels (%2)").arg(control->itemCount()).arg(control->itemAt(control->itemCount() - 1).text));
});
QObject::connect(control, &fluent::navigation::Breadcrumb::itemActivated, summary, [summary](int index, const fluent::navigation::BreadcrumbItem& item) {
    summary->setText(QStringLiteral("Opened: %1 (level %2)").arg(item.text).arg(index + 1));
});
QObject::connect(control, &fluent::navigation::Breadcrumb::overflowActivated, control, [control, overflowMenu, summary](const QVector<int>& hiddenIndexes) {
    if (hiddenIndexes.isEmpty())
        return;
    overflowMenu->clear();
    for (int index : hiddenIndexes) {
        const QString text = control->itemAt(index).text;
        auto* action = overflowMenu->addAction(text);
        QObject::connect(action, &QAction::triggered, control, [control, summary, index, text] {
            summary->setText(QStringLiteral("Opened from menu: %1 (level %2)").arg(text).arg(index + 1));
            if (control->autoTruncateOnItemClick())
                control->setItems(control->items().mid(0, index + 1));
        });
    }
    const QRect anchor = control->overflowGeometry();
    overflowMenu->popup(control->mapToGlobal(anchor.isValid() ? anchor.bottomLeft() : QPoint(0, control->height())));
});
